const protocolSelection = createProtocolSelection({
  async schema(device_type, protocol_type) {
    const response = await protocolPluginConfigForm({ device_type, protocol_type })
    if (response.error) throw new Error('schema unavailable')
    return Array.isArray(response.data) ? response.data : []
  },
  async vouchers(device_type, protocol_type) {
    const response = await deviceConfigVoucherType({ device_type, protocol_type })
    if (response.error) throw new Error('credentials unavailable')
    return response.data || {}
  },
  clear(resetData) {
    formElements.value = []
    connectOptions.value = []
    schemaFailed.value = false
    schemaKey.value++
    configFormRef.value?.restoreValidation()
    if (resetData) {
      protocol_config.value = {}
      configForm.value.voucher_type = null
    }
  },
  commit(schema, vouchers) {
    formElements.value = schema
    connectOptions.value = Object.keys(vouchers).map(label => ({ label, value: vouchers[label] }))
  },
  loading(value) { schemaLoading.value = value },
  failed() {
    schemaFailed.value = true
    message.error('协议配置加载失败，请重新选择协议后重试')
  }
})
