const handleSubmit = async () => {
  const generation = routeGeneration
  const id = configId.value
  const ready = () => generation === routeGeneration && !loading.value && !configLoading.value &&
    !configLoadFailed.value && !schemaLoading.value && !schemaFailed.value && (!id || loadedConfigId.value === id)
  if (!ready()) return
  try { await configFormRef.value?.validate() } catch { return }
  if (!ready()) return
  const { name, description, additional_info, device_conn_type, device_type, protocol_type, remark, voucher_type } = configForm.value
  const postData = { name, description, additional_info, device_conn_type, device_type, protocol_type, remark, voucher_type,
    protocol_config: JSON.stringify(protocol_config.value || {}), ...(id ? { id } : {}) }
  loading.value = true
  try {
    const res = id ? await deviceConfigEdit(postData) : await deviceConfigAdd(postData)
    if (generation !== routeGeneration) return
    if (!res.error) handleClose()
    else message.error($t(id ? 'generate.editFailed' : 'generate.addFailed'))
  } catch {
    if (generation === routeGeneration) message.error($t(id ? 'generate.editFailed' : 'generate.addFailed'))
  } finally {
    if (generation === routeGeneration) loading.value = false
  }
}

const getConfig = async (id: string, generation: number) => {
  const res = await deviceConfigInfo({ id })
  if (generation !== routeGeneration) return false
  if (res.error || !res.data || res.data.id !== id) throw new Error('Template unavailable')
  const next = defaultConfigForm()
  for (const key of Object.keys(next) as (keyof ConfigFormData)[]) {
    if (Object.prototype.hasOwnProperty.call(res.data, key)) (next as any)[key] = res.data[key]
  }
  const saved = res.data.protocol_config
  const parsed = typeof saved === 'string' ? JSON.parse(saved) : saved
  if (parsed != null && (typeof parsed !== 'object' || Array.isArray(parsed))) throw new Error('Invalid protocol configuration')
  configForm.value = next
  protocol_config.value = parsed || {}
  loadedConfigId.value = id
  return true
}

